// Legacy GEO interface of mrdoob/slop-newyork (the engine's geodata module), now backed by the Zurich inner city.
// Everything Manhattan-specific is empty; the mapped city lives in GEO.berlin (the irregular-city data path of the
// engine, see berlin-geometry.js) and is generated by tools/build-zurich-geodata.mjs.
import { ZURICH_DATA } from './zurich-geodata.js';

const [minX, minZ, maxX, maxZ] = ZURICH_DATA.meta.bounds;

export const GEO = {
  version: 2,
  city: 'Zürich',
  cityName: 'Zürich',
  irregular: true,
  frame: { bearingDeg: 0, origin: 'Bahnhofstrasse · Seidengasse (LV95 2683000 / 1247700)', units: 'm', cutZ: minZ, strip: 20, sidewalk: 3 },
  manhattan: [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ],
  upperManhattan: [],
  streets: [],
  avenues: [],
  broadway: [],
  piers: [],
  islands: {},
  boroughs: { newJersey: [], brooklyn: [], queens: [], bronx: [], statenIsland: [] },
  bridges: {},
  points: {},
  plazas: [],
  centralPark: { bounds: { minX, maxX, minZ, maxZ }, lawns: [], water: ZURICH_DATA.water, drives: [] },
  parks: ZURICH_DATA.parks.map((p) => ({ name: p.name, kind: p.kind, rings: [p.ring], holes: p.holes })),
  landmarks: ZURICH_DATA.landmarks,
  roads: [],
  blocks: [],
  roadGraph: ZURICH_DATA.roadGraph,
  berlin: ZURICH_DATA
};
